css:
.intangiblesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #d7e3ee;
    background: radial-gradient(1200px 600px at 20% -10%, #14233a 0%, #0a1525 55%, #060d18 100%);
    border-radius: 18px;
}

.intangiblesim-container * {
    box-sizing: border-box;
}

.intangiblesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0b1c33 0%, #102b4d 55%, #14406b 100%);
    color: #eaf3ff;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #1d3a5f;
    box-shadow: 0 12px 34px rgba(0, 0, 0, 0.45);
}

.intangiblesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #f4f9ff;
}

.intangiblesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #6fe3c4;
    background: rgba(111, 227, 196, 0.10);
    border: 1px solid rgba(111, 227, 196, 0.28);
    padding: 5px 14px;
    border-radius: 999px;
}

.intangiblesim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #b6c8db;
}

.intangiblesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9fb6cf;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.intangiblesim-period-counter #currentDay,
.intangiblesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #6fe3c4;
}

.intangiblesim-round-name {
    background: #122a45;
    color: #8fd9ff;
    border: 1px solid #214a72;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.intangiblesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffcf8a;
    background: rgba(255, 168, 64, 0.12);
    border: 1px solid rgba(255, 168, 64, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.intangiblesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.intangiblesim-status-card {
    background: linear-gradient(180deg, #0f2138 0%, #0b1828 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #1c3553;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
    border-top: 4px solid #2f80c8;
}

.intangiblesim-card-rigour { border-top-color: #2f9cc8; }
.intangiblesim-card-robust { border-top-color: #7d6cf0; }
.intangiblesim-card-cred { border-top-color: #6fe3c4; }
.intangiblesim-card-value { border-top-color: #ffb347; }

.intangiblesim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7f96b0;
}

.intangiblesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #eaf3ff;
    font-variant-numeric: tabular-nums;
}

.intangiblesim-card-rigour .intangiblesim-value { color: #4cb6e0; }
.intangiblesim-card-robust .intangiblesim-value { color: #9d8efb; }
.intangiblesim-card-cred .intangiblesim-value { color: #6fe3c4; }
.intangiblesim-card-value .intangiblesim-value { color: #ffc26b; }

.intangiblesim-sublabel {
    font-size: 0.75rem;
    color: #7f96b0;
    line-height: 1.35;
}

.intangiblesim-cred-low .intangiblesim-value { color: #ff6b6b; }
.intangiblesim-cred-high .intangiblesim-value { color: #6fe3c4; }

.intangiblesim-value-inrange .intangiblesim-value { color: #6fe3c4; }
.intangiblesim-value-outrange .intangiblesim-value { color: #ff8a5b; }

.intangiblesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0b1c33;
    color: #cfe2f5;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border: 1px solid #1c3553;
}

.intangiblesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #8fd9ff;
    font-variant-numeric: tabular-nums;
}

.intangiblesim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(180deg, #0f2138 0%, #0b1828 100%);
    border-left: 5px solid #2f9cc8;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #1c3553;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
}

.intangiblesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.intangiblesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #eaf3ff;
    margin-bottom: 6px;
}

.intangiblesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #b6c8db;
}

.intangiblesim-briefing-text strong { color: #6fe3c4; }
.intangiblesim-briefing-text em { color: #ffcf8a; font-style: italic; }

.intangiblesim-controls {
    background: linear-gradient(180deg, #0e1f35 0%, #0a1727 100%);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #1c3553;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
}

.intangiblesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #eaf3ff;
    border-bottom: 2px solid #1c3553;
    padding-bottom: 8px;
}

.intangiblesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #cfe0f2;
    margin: 14px 0 6px;
}

.intangiblesim-container select,
.intangiblesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #284a70;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0c1d31;
    color: #eaf3ff;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.intangiblesim-container select:focus,
.intangiblesim-container input[type="number"]:focus {
    outline: none;
    border-color: #6fe3c4;
    box-shadow: 0 0 0 3px rgba(111, 227, 196, 0.18);
}

.intangiblesim-container select option {
    background-color: #0c1d31;
    color: #eaf3ff;
}

.intangiblesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #6fe3c4;
}

.intangiblesim-range-readout,
.intangiblesim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb6cf;
    margin-top: 4px;
}

.intangiblesim-range-readout span:last-child,
.intangiblesim-alloc-readout span:nth-child(2) {
    color: #6fe3c4;
    font-weight: 800;
    font-variant-numeric: tabular-nums;
}

.intangiblesim-hint {
    font-size: 0.8rem;
    color: #7f96b0;
    margin-top: 4px;
    line-height: 1.4;
}

.intangiblesim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.intangiblesim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #0c1d31;
    border: 1px solid #1c3553;
    border-radius: 9px;
    padding: 8px 12px;
}

.intangiblesim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #c2d4e7;
}

.intangiblesim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.intangiblesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.intangiblesim-container .btn-primary {
    background: linear-gradient(135deg, #1f9c8c 0%, #2f9cc8 100%);
    border: none;
    color: #04121d;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(47, 156, 200, 0.28);
}

.intangiblesim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.intangiblesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #284a70;
    color: #9fb6cf;
}

.intangiblesim-coach {
    background: linear-gradient(180deg, #102b4d 0%, #0b1c33 100%);
    color: #dbe9f8;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid #214a72;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.38);
}

.intangiblesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #6fe3c4;
    margin-bottom: 8px;
}

.intangiblesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.intangiblesim-coach-body strong { color: #ffd98a; }
.intangiblesim-coach-body em { color: #8fd9ff; font-style: italic; }

.intangiblesim-history,
.intangiblesim-chart {
    background: linear-gradient(180deg, #0e1f35 0%, #0a1727 100%);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #1c3553;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.30);
}

.intangiblesim-history h3,
.intangiblesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #eaf3ff;
}

.intangiblesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #c2d4e7;
}

.intangiblesim-container table#usfHistoryTable th {
    background: #0c1d31;
    color: #8fd9ff;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #214a72;
}

.intangiblesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #16293f;
    color: #c2d4e7;
}

.intangiblesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(255, 255, 255, 0.02);
}

.intangiblesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .intangiblesim-container {
        padding: 14px;
    }
    .intangiblesim-header h1 {
        font-size: 1.7rem;
    }
    .intangiblesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .intangiblesim-value {
        font-size: 1.9rem;
    }
    .intangiblesim-clock {
        margin-left: 0;
    }
    .intangiblesim-period-counter {
        font-size: 0.88rem;
    }
    .intangiblesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .intangiblesim-alloc-row {
        flex-wrap: wrap;
    }
    .intangiblesim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .intangiblesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen ---- */
.intangiblesim-completion { padding: 8px 4px 4px; }
.intangiblesim-cm-head { text-align: center; margin-bottom: 16px; }
.intangiblesim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #6fe3c4; }
.intangiblesim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #8fd9ff; }
.intangiblesim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #eaf3ff; }
.intangiblesim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.intangiblesim-cm-yes { background: rgba(111,227,196,0.16); color: #6fe3c4; border: 1px solid rgba(111,227,196,0.45); }
.intangiblesim-cm-no { background: rgba(255,127,127,0.14); color: #ff9b9b; border: 1px solid rgba(255,127,127,0.5); }
.intangiblesim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.intangiblesim-cm-metric { flex: 1 1 120px; min-width: 108px; background: rgba(143,217,255,0.08); border: 1px solid rgba(143,217,255,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.intangiblesim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #8fd9ff; }
.intangiblesim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #9fb6cf; text-transform: uppercase; letter-spacing: 0.03em; }
.intangiblesim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #eaf3ff; }
.intangiblesim-cm-insights { margin: 0; padding-left: 20px; }
.intangiblesim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #cfe0f2; }

js:
(function() {
    'use strict';

    class IntangibleAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Valuing the Intangible`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (EUR).
            this.IPO_LOW = 1.4;          // EUR bn equity value, low end
            this.IPO_HIGH = 1.9;         // EUR bn equity value, high end
            this.IPO_MID = 1.65;         // EUR bn equity value, midpoint
            this.DCF_FLOOR = 0.75;       // EUR bn — near-term-cash-flow DCF (no-earnings lens)
            this.START_VALUE = 0.80;     // EUR bn — naive earnings-anchored starting estimate
            this.HOURS_CAP = 120;        // analyst-hours available over 6 trading days
            this.TARGET_RIGOUR = 70;     // a publishable, defensible valuation
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    rigour: 20,
                    robust: 15,
                    cred: 50,
                    estimate: this.START_VALUE,   // EUR bn central equity estimate
                    hoursUsed: 0,
                    doubleCounted: false,
                    inRange: false,
                    rigourHistory: [20],
                    robustHistory: [15],
                    credHistory: [50],
                    estimateHistory: [this.START_VALUE],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    lens: `intangible`,
                    dcf: 40, multiple: 35, sotp: 15, realopt: 10,
                    question: 60,
                    clv: `cohort`, rd: `economic`, double: `oneroute`, moat: 6,
                    wacc: 10, tg: 3, margin: 25, output: `range`, keyrisk: `fade`,
                    news: `retest`, indep: `independent`, rating: `hold`, defence: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const lens = document.getElementById(`lensInput`);
                const q = document.getElementById(`questionInput`);
                if (lens) decisions.lens = lens.value;
                if (q) decisions.question = parseInt(q.value, 10);
                const dcf = document.getElementById(`dcfInput`);
                const mult = document.getElementById(`multipleInput`);
                const sotp = document.getElementById(`sotpInput`);
                const ro = document.getElementById(`realoptInput`);
                if (dcf) decisions.dcf = parseFloat(dcf.value);
                if (mult) decisions.multiple = parseFloat(mult.value);
                if (sotp) decisions.sotp = parseFloat(sotp.value);
                if (ro) decisions.realopt = parseFloat(ro.value);
                const parts = [decisions.dcf, decisions.multiple, decisions.sotp, decisions.realopt];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_weight_negative`); return false;
                }
                const total = Math.round(decisions.dcf + decisions.multiple + decisions.sotp + decisions.realopt);
                if (total !== 100) {
                    warn(`warn_weight_total`); return false;
                }
                if (!Number.isFinite(decisions.question) || decisions.question < 0 || decisions.question > 100) {
                    warn(`warn_question_range`); return false;
                }
            } else if (round === 2) {
                const clv = document.getElementById(`clvInput`);
                const rd = document.getElementById(`rdInput`);
                const db = document.getElementById(`doubleInput`);
                const moat = document.getElementById(`moatInput`);
                if (clv) decisions.clv = clv.value;
                if (rd) decisions.rd = rd.value;
                if (db) decisions.double = db.value;
                if (moat) decisions.moat = parseFloat(moat.value);
                if (!Number.isFinite(decisions.moat) || decisions.moat < 0 || decisions.moat > 20) {
                    warn(`warn_moat_range`); return false;
                }
            } else if (round === 3) {
                const wacc = document.getElementById(`waccInput`);
                const tg = document.getElementById(`tgInput`);
                const margin = document.getElementById(`marginInput`);
                const out = document.getElementById(`outputInput`);
                const kr = document.getElementById(`keyriskInput`);
                if (wacc) decisions.wacc = parseFloat(wacc.value);
                if (tg) decisions.tg = parseFloat(tg.value);
                if (margin) decisions.margin = parseFloat(margin.value);
                if (out) decisions.output = out.value;
                if (kr) decisions.keyrisk = kr.value;
                if (!Number.isFinite(decisions.wacc) || decisions.wacc < 7 || decisions.wacc > 14) {
                    warn(`warn_wacc_range`); return false;
                }
                if (!Number.isFinite(decisions.tg) || decisions.tg < 1 || decisions.tg > 6) {
                    warn(`warn_tg_range`); return false;
                }
                if (!Number.isFinite(decisions.margin) || decisions.margin < 5 || decisions.margin > 40) {
                    warn(`warn_margin_range`); return false;
                }
                // A terminal growth at or above the discount rate breaks the Gordon model.
                if (decisions.tg >= decisions.wacc) {
                    warn(`warn_tg_wacc`); return false;
                }
            } else if (round === 4) {
                const news = document.getElementById(`newsInput`);
                const indep = document.getElementById(`indepInput`);
                const rating = document.getElementById(`ratingInput`);
                const def = document.getElementById(`defenceInput`);
                if (news) decisions.news = news.value;
                if (indep) decisions.indep = indep.value;
                if (rating) decisions.rating = rating.value;
                if (def) decisions.defence = parseInt(def.value, 10);
                if (!Number.isFinite(decisions.defence) || decisions.defence < 0 || decisions.defence > 100) {
                    warn(`warn_defence_range`); return false;
                }
            }
            return true;
        }

        // Pure helper: a stylised DCF/Gordon valuation in EUR bn from the key assumptions.
        // Higher terminal growth and margin lift value; higher WACC cuts it. The moat premium
        // slows the fade and so lifts durable value. Output is clamped to a sane band.
        _modelValue(wacc, tg, margin, moatPremium) {
            const spread = Math.max(0.5, wacc - tg);                 // discount-rate minus growth
            const marginFactor = 0.6 + (margin / 25) * 0.7;          // 25% margin ~ 1.3x
            const durability = 1 + (moatPremium / 100) * 2.4;        // a real moat slows the fade
            // Base anchored so that wacc=10, tg=3, margin=25, moat=6 lands near the IPO midpoint (~€1.65bn);
            // the defensible sane band reaches into the €1.4–1.9bn range, and bear cases fall below it.
            let v = (4.6 / spread) * marginFactor * durability * 1.6883;
            return Math.max(0.55, Math.min(2.6, v));
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let rigourDelta = 0, robustDelta = 0, credDelta = 0;
            let hours = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                hours = 24;
                // Common Error 1 — book-value / no-earnings anchoring.
                switch (d.lens) {
                    case `intangible`: rigourDelta += 16; credDelta += 6; coachKey = `coach_r1_intangible`; break;
                    case `bookvalue`: rigourDelta -= 14; credDelta -= 6; coachKey = `coach_r1_bookvalue`; break;
                    case `earnings`: rigourDelta -= 12; credDelta -= 5; coachKey = `coach_r1_earnings`; break;
                    case `momentum`: rigourDelta -= 8; credDelta -= 4; coachKey = `coach_r1_momentum`; break;
                }

                // Choosing & weighting methods. A spread that leans on DCF + multiples while
                // keeping SOTP/real-options as a sanity check is the triangulated answer.
                const triangulated = d.dcf >= 25 && d.multiple >= 25 && d.realopt <= 25 && d.sotp <= 30;
                const oneMethod = (d.dcf >= 80 || d.multiple >= 80 || d.sotp >= 80 || d.realopt >= 80);
                const speculative = d.realopt >= 40;
                if (oneMethod) {
                    rigourDelta -= 10; robustDelta -= 8; coachKey = `coach_r1_onemethod`;
                } else if (speculative) {
                    rigourDelta -= 4; coachKey = `coach_r1_speculative`;
                } else if (triangulated) {
                    rigourDelta += 12; robustDelta += 8; if (d.lens === `intangible`) coachKey = `coach_r1_triangulated`;
                } else {
                    rigourDelta += 4; robustDelta += 2;
                }

                // Stating the investment question clearly.
                if (d.question >= 60) { rigourDelta += 6; credDelta += 3; }
                else if (d.question <= 25) { rigourDelta -= 6; coachKey = `coach_r1_noquestion`; }

                summaryKey = (d.lens === `intangible` && triangulated && !oneMethod) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                hours = 32;
                // Customer base as an asset via cohort economics.
                switch (d.clv) {
                    case `cohort`: rigourDelta += 12; robustDelta += 4; coachKey = `coach_r2_cohort`; break;
                    case `headcount`: rigourDelta -= 4; coachKey = `coach_r2_headcount`; break;
                    case `ignore`: rigourDelta -= 8; credDelta -= 3; coachKey = `coach_r2_ignore`; break;
                }

                // Common Error 4 — mechanical R&D adjustment vs economic rationale.
                switch (d.rd) {
                    case `economic`: rigourDelta += 12; robustDelta += 4; coachKey = (d.clv === `cohort`) ? `coach_r2_rd_economic` : coachKey; break;
                    case `mechanical`: rigourDelta -= 6; coachKey = `coach_r2_rd_mechanical`; break;
                    case `leave`: rigourDelta -= 8; coachKey = `coach_r2_rd_leave`; break;
                }

                // Common Error 3 — double-counting intangibles.
                switch (d.double) {
                    case `oneroute`: rigourDelta += 12; robustDelta += 6; credDelta += 4; break;
                    case `both`: rigourDelta -= 14; credDelta -= 6; ds.doubleCounted = true; coachKey = `coach_r2_double`; break;
                    case `neither`: rigourDelta -= 6; robustDelta -= 2; coachKey = `coach_r2_neither`; break;
                }

                // Moat → growth-durability premium. A modest, defensible premium is rewarded;
                // an inflated one is "an imagined moat" that hurts robustness.
                if (d.moat >= 3 && d.moat <= 9) { rigourDelta += 6; robustDelta += 3; }
                else if (d.moat > 12) { robustDelta -= 6; rigourDelta -= 3; coachKey = `coach_r2_moat_high`; }
                else if (d.moat === 0) { rigourDelta -= 2; }

                summaryKey = (d.clv === `cohort` && d.rd === `economic` && d.double === `oneroute`) ? `sum_r2_good` : (ds.doubleCounted ? `sum_r2_double` : `sum_r2_weak`);
            } else if (round === 3) {
                hours = 36;
                // Build the integrated value from the assumptions, then reconcile with the range.
                const modelV = this._modelValue(d.wacc, d.tg, d.margin, d.moat);
                ds.estimate = Math.round(modelV * 100) / 100;

                // Common Error 2 — single point / single method, or back-solving to the banker range.
                switch (d.output) {
                    case `range`: rigourDelta += 10; robustDelta += 18; coachKey = `coach_r3_range`; break;
                    case `point`: robustDelta -= 14; rigourDelta -= 4; coachKey = `coach_r3_point`; break;
                    case `anchor`: robustDelta -= 8; credDelta -= 8; rigourDelta -= 6; coachKey = `coach_r3_anchor`; break;
                }

                // Naming the single key-risk assumption — growth durability (the fade) is correct.
                switch (d.keyrisk) {
                    case `fade`: robustDelta += 12; rigourDelta += 4; if (d.output === `range`) coachKey = `coach_r3_fade`; break;
                    case `wacc`: robustDelta += 4; break;
                    case `none`: robustDelta -= 12; coachKey = `coach_r3_norisk`; break;
                }

                // Reasonable-band assumptions reward robustness; extreme ones (used to hit the
                // banker range) are flagged. tg<wacc is already enforced in validation.
                const sane = (d.wacc >= 8.5 && d.wacc <= 12) && (d.tg <= 4) && (d.margin >= 18 && d.margin <= 32);
                if (sane) { robustDelta += 6; rigourDelta += 4; }
                else { robustDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r3_extreme`; }

                // Reconcile with the EUR 1.4–1.9bn range. Landing inside (honestly) builds credibility;
                // a wildly low estimate signals book-value anchoring survived.
                ds.inRange = ds.estimate >= this.IPO_LOW && ds.estimate <= this.IPO_HIGH;
                if (ds.inRange) { credDelta += 6; }
                else if (ds.estimate < this.DCF_FLOOR + 0.05) { credDelta -= 4; }

                summaryKey = (d.output === `range` && d.keyrisk === `fade` && sane) ? `sum_r3_good` : (d.output === `point` || d.output === `anchor` ? `sum_r3_point` : `sum_r3_weak`);
            } else if (round === 4) {
                hours = 28;
                // Live assumptions: the competitor + customer-concentration news must move the model.
                switch (d.news) {
                    case `retest`: rigourDelta += 10; robustDelta += 10; credDelta += 6; coachKey = `coach_r4_retest`; break;
                    case `hold`: rigourDelta -= 8; robustDelta -= 6; credDelta -= 4; coachKey = `coach_r4_holdnews`; break;
                    case `panic`: rigourDelta -= 6; robustDelta -= 4; coachKey = `coach_r4_panic`; break;
                }

                // Common Error 5 — compromised independence under banking pressure.
                switch (d.indep) {
                    case `independent`: credDelta += 18; rigourDelta += 4; coachKey = (d.news === `retest`) ? `coach_r4_independent` : coachKey; break;
                    case `soften`: credDelta -= 22; rigourDelta -= 6; coachKey = `coach_r4_soften`; break;
                    case `withdraw`: credDelta -= 6; coachKey = `coach_r4_withdraw`; break;
                }

                // The rating must follow the model. With the estimate near/below mid and fresh
                // downside news, "hold" is the defensible call; "buy at the top" abandons the model.
                const estimate = ds.estimate;
                if (d.rating === `hold`) {
                    if (estimate >= this.IPO_LOW && estimate <= this.IPO_HIGH) { credDelta += 10; rigourDelta += 4; }
                    else { credDelta += 4; }
                    if (d.indep === `independent`) coachKey = `coach_r4_holdcall`;
                } else if (d.rating === `buy`) {
                    if (estimate >= this.IPO_HIGH) { credDelta += 4; }
                    else { credDelta -= 12; rigourDelta -= 4; coachKey = `coach_r4_buyhigh`; }
                } else if (d.rating === `sell`) {
                    if (estimate < this.IPO_LOW - 0.1) { credDelta += 4; }
                    else { credDelta -= 10; coachKey = `coach_r4_sellanchor`; }
                }

                // Conviction in the IC defence.
                credDelta += Math.round((d.defence - 60) / 8);

                summaryKey = (d.news === `retest` && d.indep === `independent` && d.rating === `hold`) ? `sum_r4_good` : (d.indep === `soften` ? `sum_r4_compromised` : `sum_r4_weak`);
            }

            // Resource accounting.
            ds.hoursUsed = Math.min(this.HOURS_CAP, ds.hoursUsed + hours);

            // Metrics move on their deltas, clamped 0–100.
            ds.rigour = Math.max(0, Math.min(100, ds.rigour + rigourDelta));
            ds.robust = Math.max(0, Math.min(100, ds.robust + robustDelta));
            ds.cred = Math.max(0, Math.min(100, ds.cred + credDelta));

            ds.rigourHistory.push(Math.round(ds.rigour));
            ds.robustHistory.push(Math.round(ds.robust));
            ds.credHistory.push(Math.round(ds.cred));
            ds.estimateHistory.push(ds.estimate);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose the composite valuation score (0-100) to the reporting/grading layer every
            // period (express/results_utils.php::express_resolveDomainScore reads
            // domainState.performance.overallScore). The final period locks the authoritative grade.
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                rigour: Math.round(ds.rigour),
                rigourDelta: Math.round(rigourDelta),
                robust: Math.round(ds.robust),
                robustDelta: Math.round(robustDelta),
                cred: Math.round(ds.cred),
                credDelta: Math.round(credDelta),
                estimate: ds.estimate,
                inRange: ds.inRange,
                doubleCounted: ds.doubleCounted,
                hoursUsed: ds.hoursUsed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
