            uiManager.bind(`rigourDisplay`, `domainState.rigour`, (v) => Math.round(v));
            uiManager.bind(`robustDisplay`, `domainState.robust`, (v) => Math.round(v));
            uiManager.bind(`credDisplay`, `domainState.cred`, (v) => {
                const card = document.querySelector(`.intangiblesim-card-cred`);
                if (card) {
                    card.classList.toggle(`intangiblesim-cred-high`, Number(v) >= 70);
                    card.classList.toggle(`intangiblesim-cred-low`, Number(v) < 40);
