                    card.classList.toggle(`intangiblesim-value-inrange`, inRange);
                    card.classList.toggle(`intangiblesim-value-outrange`, !inRange);
                }
                return `€` + n.toFixed(2) + `bn`;
            });
            uiManager.bind(`budgetDisplay`, `domainState.hoursUsed`, (v) => Math.round(Number(v)) + `h / 120h`);

            const self = this;

            // Method-weight live total.
            const wIds = [`dcfInput`, `multipleInput`, `sotpInput`, `realoptInput`];
            const weightReadout = document.getElementById(`weightReadout`);
            const recompute = function() {
                let total = 0;
                wIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (weightReadout) weightReadout.textContent = total;
                const bar = document.querySelector(`.intangiblesim-alloc-readout`);
                if (bar) bar.style.color = (total !== 100) ? `#ff8a5b` : ``;
            };
            wIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();

            // Slider readouts.
            const sliders = [
                [`questionInput`, `questionReadout`],
                [`waccInput`, `waccReadout`],
                [`tgInput`, `tgReadout`]
            ];
            sliders.forEach(([inId, outId]) => {
                const inEl = document.getElementById(inId);
                const outEl = document.getElementById(outId);
                if (inEl && outEl) {
                    outEl.textContent = inEl.value;
                    inEl.addEventListener(`input`, function() { outEl.textContent = inEl.value; });
                }
            });
        }

