        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.rigourHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                valuationChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.rigourHistory },
                        { data: ds.robustHistory },
                        { data: ds.credHistory }
                    ]
                }
            };
