        // Composite valuation score (0-100). Written to domainState.performance.overallScore each
        // period for the reporting/grading layer. Formula copied VERBATIM from v1.0.0
        // getPerformanceSummary (rigour 0.35 / robust 0.30 / cred 0.35).
        _composite(ds) {
            const rigour = Math.round(ds.rigour || 0);
            const robust = Math.round(ds.robust || 0);
            const cred = Math.round(ds.cred || 0);
            const composite = Math.round(rigour * 0.35 + robust * 0.30 + cred * 0.35);
            return Math.max(0, Math.min(100, composite));
        }

        // Safe chart-legend localizer: translated label, or English fallback if i18n isn't ready.
        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        // Override the framework's generic "you completed N periods" modal with the real grade,
        // score, KPI strip and localized debrief the sim already computes.
        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.overallScore === `number` ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!(s.defensible && s.independent);
            const badge = met
                ? `<span class="intangiblesim-cm-badge intangiblesim-cm-yes">` + T(`cm_won`) + `</span>`
                : `<span class="intangiblesim-cm-badge intangiblesim-cm-no">` + T(`cm_notwon`) + `</span>`;
            const riskBadge = (s.cred != null && Number(s.cred) < 40)
                ? ` <span class="intangiblesim-cm-badge intangiblesim-cm-no">` + T(`cm_atrisk`) + `</span>`
                : ``;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const estStr = (s.estimate != null) ? String(s.estimate) : ``;
            const metrics = ``
                + `<div class="intangiblesim-cm-metric"><span class="intangiblesim-cm-mv">` + Math.round(s.rigour || 0) + `</span><span class="intangiblesim-cm-ml">` + T(`cm_m_quality`) + `</span></div>`
                + `<div class="intangiblesim-cm-metric"><span class="intangiblesim-cm-mv">` + Math.round(s.robust || 0) + `</span><span class="intangiblesim-cm-ml">` + T(`cm_m_robust`) + `</span></div>`
                + `<div class="intangiblesim-cm-metric"><span class="intangiblesim-cm-mv">` + Math.round(s.cred || 0) + `</span><span class="intangiblesim-cm-ml">` + T(`cm_m_cred`) + `</span></div>`
                + `<div class="intangiblesim-cm-metric"><span class="intangiblesim-cm-mv">` + estStr + `</span><span class="intangiblesim-cm-ml">` + T(`cm_m_estimate`) + `</span></div>`;
            return ``
                + `<div class="intangiblesim-completion">`
                +   `<div class="intangiblesim-cm-head">`
                +     `<div class="intangiblesim-cm-score">` + score + `<span class="intangiblesim-cm-score-max">/100</span></div>`
                +     `<div class="intangiblesim-cm-grade">` + grade + ` ` + badge + riskBadge + `</div>`
                +   `</div>`
                +   `<div class="intangiblesim-cm-metrics">` + metrics + `</div>`
                +   `<div class="intangiblesim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="intangiblesim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const rigour = Math.round(ds.rigour);
            const robust = Math.round(ds.robust);
            const cred = Math.round(ds.cred);
            const estimate = ds.estimate;

            const defensible = rigour >= this.TARGET_RIGOUR && robust >= 60;
            const independent = cred >= 60;
            const composite = Math.round(rigour * 0.35 + robust * 0.30 + cred * 0.35);

            let performanceKey = `grade_indefensible`;
            if (defensible && independent && composite >= 75) performanceKey = `grade_streetleading`;
            else if (defensible && independent) performanceKey = `grade_credible`;
            else if (defensible && !independent) performanceKey = `grade_compromised`;
            else if (cred < 40) performanceKey = `grade_damaged`;
            else if (composite >= 50) performanceKey = `grade_roughly`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (defensible && independent) insights.push(window.mySimulation.t(`insight_strong`));
            else if (defensible && !independent) insights.push(window.mySimulation.t(`insight_compromised`));
            else insights.push(window.mySimulation.t(`insight_weak`));

            if (ds.doubleCounted) insights.push(window.mySimulation.t(`insight_double`));
            if (robust < 45) insights.push(window.mySimulation.t(`insight_point`));
            if (cred < 40) insights.push(window.mySimulation.t(`insight_lowcred`));
            if (ds.inRange) insights.push(window.mySimulation.t(`insight_inrange`));

            return {
                rigour: rigour,
                robust: robust,
                cred: cred,
                estimate: `€` + estimate.toFixed(2) + `bn`,
                inRange: ds.inRange,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                defensible: defensible,
                independent: independent,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.doubleCounted) return window.mySimulation.t(`hint_double`);
            if (ds.cred < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_cred`);
            if (ds.robust < 35 && state.currentPeriod >= 3) return window.mySimulation.t(`hint_robust`);
            if (ds.rigour < 35) return window.mySimulation.t(`hint_rigour`);
            if (ds.rigour >= this.TARGET_RIGOUR && ds.robust >= 60 && ds.cred >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

